  hexxy=np.column_stack([t.array_col/2,np.sqrt(3)*t.array_row/2]);assert np.allclose(np.linalg.norm(hexxy[ii]-hexxy[jj],axis=1),1);ncomp,comp=connected_components(g,directed=False);t['physical_component']=comp;t['x_pitch']=xy[:,0]/pitch;t['y_pitch']=xy[:,1]/pitch;t['pitch_px']=pitch
